<?php
require "koneksi.php";
$halaman_aktif_publik = 'beranda';
$jenis_q = mysqli_query($koneksi, "SELECT j.*, u.gambar AS gambar_kartu, u.urutan FROM ui_category_cards u JOIN jenis_buku j ON j.id_jenis=u.id_jenis WHERE j.status='Aktif' AND u.aktif=1 ORDER BY u.urutan ASC LIMIT 8");
$favorit = mysqli_query($koneksi, "SELECT b.*, j.nama_jenis FROM buku b LEFT JOIN jenis_buku j ON j.id_jenis=b.id_jenis WHERE b.favorit=1 ORDER BY b.id_buku ASC LIMIT 6");
$terbaru = mysqli_query($koneksi, "SELECT b.*, j.nama_jenis FROM buku b LEFT JOIN jenis_buku j ON j.id_jenis=b.id_jenis ORDER BY b.created_at DESC, b.id_buku DESC LIMIT 6");
?>
