<script>function bukaDetail(id){document.getElementById('modalDetail').classList.add('show');fetch('detail_buku.php?id='+id).then(r=>r.text()).then(h=>document.getElementById('isiModal').innerHTML=h)}function tutupDetail(){document.getElementById('modalDetail').classList.remove('show')}document.getElementById('modalDetail').addEventListener('click',e=>{if(e.target===e.currentTarget)tutupDetail()});</script></body></html>